async function callTool(req) {
  const auth = req.headers["authorization"];   // the client's bearer token
  const res = await fetch(TRACKER + "/issues", {
    method: "POST",
    headers: { authorization: auth },          // forwarded unchanged
    body: JSON.stringify(req.params.arguments),
  });
  return { content: [{ type: "text", text: await res.text() }] };
}

